#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint32_t my_htonl(uint32_t v) {
    return ((v & 0x000000FFu) << 24) | ((v & 0x0000FF00u) << 8)
         | ((v & 0x00FF0000u) >> 8)  | ((v & 0xFF000000u) >> 24);
}

int main(void) {
    uint32_t v = 0x01020304u;
    unsigned char bytes[4];
    unsigned char nb[4];
    uint32_t net;
    int little;
    const char *s = "AB";
    unsigned char sb[2];

    memcpy(bytes, &v, 4);
    little = (bytes[0] == 0x04);

    printf("=== endianness ===\n");
    printf("  v = 0x%08X stored as bytes: %02X %02X %02X %02X\n",
           v, bytes[0], bytes[1], bytes[2], bytes[3]);
    printf("  this machine is %s-endian\n", little ? "little" : "big");
    printf("  the byte at the LOWEST address is %02X, i.e. the %s byte of v\n",
           bytes[0], little ? "LEAST significant" : "MOST significant");

    net = my_htonl(v);
    memcpy(nb, &net, 4);
    printf("\n=== htonl written by hand ===\n");
    printf("  my_htonl(0x%08X) = 0x%08X  -> bytes %02X %02X %02X %02X (big-endian order)\n",
           v, net, nb[0], nb[1], nb[2], nb[3]);
    printf("  on a little-endian host htonl is a plain byte swap: %s\n", (v != net) ? "yes" : "no");
    printf("  double htonl(htonl(v)) cancels out: %s\n", (my_htonl(my_htonl(v)) == v) ? "yes" : "no");

    printf("\n=== byte strings are never swapped ===\n");
    memcpy(sb, s, 2);
    printf("  \"AB\" bytes: %02X %02X  (a char array has no multi-byte scalar to reorder)\n", sb[0], sb[1]);

    printf("\n=== practical rule ===\n");
    printf("  every multi-byte field written to a file or a socket needs an explicit byte order\n");
    printf("  never write a raw struct: padding, endianness and version all leak into the format\n");
    return 0;
}
